(()=>{let e=!1;const t=()=>{if(e)return;e=!0;const t=document.querySelectorAll(".section.about, .section.value");if(t.length>0&&"IntersectionObserver"in window){const e=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.querySelectorAll(".counter-wrapper, .about-counter-wrap, .counter-overflow, .value-single-block").forEach(e=>{e.classList.add("counted")}),t.unobserve(e.target))})},{rootMargin:"100px 0px",threshold:.1});t.forEach(t=>e.observe(t))}};["scroll","pointerdown","touchstart"].forEach(e=>{window.addEventListener(e,t,{once:!0,passive:!0})})})();